mapper.select:
SELECT T7.PAY_TYPE etrPayType, T8.BID_PRIN_AMT bidPriceTotal, T5.WIN_PRIN_AMT winPriceTotal, T1.ENTRUST_DATE entrustDate, t8.IS_WIN isWin, t8.BID_PRICE bidPrice, t5.WIN_PRICE winPriceStr, T1.ENTRUST_ID ENTRUSTID, T1.ENTRUST_STATUS ENTRUSTSTATUS, T12.REAL_NAME INVMANAGERID, T1.PORTFOLIO_ID PORTFOLIOID, T2.PORTFOLIO_NAME PORTFOLIONAME, T1.FINPROD_ID FINPRODID, T3.FINPROD_MARKET_ID FINPRODMARKETID, T3.FINPROD_ABBR FINPRODABBR, T3.FINPROD_NAME FINPRODNAME, T1.PS PS, T1.TRADE_MARKET TRADEMARKET, T1.TRADE_PLAT TRADEPLAT, T1.TRADE_MARKET_MODE TRADEMARKETMODE, T1.ENTRUST_NUM * 100 ENTRUSTNUM, T1.CCY CCY, T1.VDATE VDATE, T1.MDATE MDATE, T1.REMARK REMARK, T1.INV_AIM INVAIM, T7.SETTLE_SPREED SETTLESPREED, T7.ASSET_TYPE1 ASSETTYPE1,
T7.ASSET_TYPE_10 assetType10, T7.ASSET_TYPE_11 assetType11
FROM ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T11 ON T11.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T11.USER_ID = #{userId} LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T3.FINPROD_ID LEFT JOIN (SELECT ORDPRICE.ENTRUST_ID, SUM(ORDPRICE.WIN_PRIN_AMT) WIN_PRIN_AMT, LISTAGG(CASE WHEN ORDPRICE.WIN_PRICE IS NULL THEN NULL ELSE ORDPRICE.WIN_PRICE * 100 || '%' END) WIN_PRICE FROM BID_ORDER_BID_PRICE ORDPRICE GROUP BY ORDPRICE.ENTRUST_ID) T5 ON T5.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN (SELECT T9.ENTRUST_ID, SUM(T9.BID_PRIN_AMT) BID_PRIN_AMT , T10.BID_ID, T10.IS_WIN IS_WIN2, LISTAGG(T9.BID_PRICE * 100 , '%') BID_PRICE, CASE WHEN T10.BID_ID IS NULL THEN '01'
WHEN T10.IS_WIN IS NOT NULL THEN T10.IS_WIN ELSE '02' END IS_WIN FROM ETR_ENTRUST_BID_PRICE T9 LEFT JOIN BID_ORDER_BID_PRICE T10 ON T10.ENTRUST_ID = T9.ENTRUST_ID AND T10.BID_PRICE = T9.BID_PRICE GROUP BY T9.ENTRUST_ID, T10.BID_ID, T10.IS_WIN) T8 ON T8.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T12 ON T1.INV_MANAGER_ID = T12.USER_NAME
AND T1.FINPROD_TYPE2 =#{bond}
AND (T1.PORTFOLIO_ID IN
null) OR T1.PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
OR T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
)
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) or T3.FINPROD_ABBR like concat('%',concat(#{finprodId},'%')))
AND T1.TRADE_MARKET=#{tradeMarket}
AND T1.TRADE_PLAT=#{tradePlat}
AND T1.PS=#{ps}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE >=to_date(#{bidStartDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{bidEndDate},'yyyy-MM-dd')
AND T7.ASSET_TYPE1 in
#{item}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T8.IS_WIN = #{bidStatus}
order by T1.ENTRUST_ID DESC
